BEGIN;

CREATE TABLE IF NOT EXISTS "portfolio_education" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "degree" varchar(200) NOT NULL CHECK (length(btrim("degree")) > 0),
  "institution" varchar(200) NOT NULL CHECK (length(btrim("institution")) > 0),
  "year" varchar(40) NOT NULL CHECK (length(btrim("year")) > 0),
  "version" integer NOT NULL DEFAULT 1 CHECK ("version" > 0),
  "deletedAt" timestamptz NULL
);

ALTER TABLE "portfolio_education" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE "portfolio_education" FROM PUBLIC;

COMMIT;
